mapper.select:
SELECT p.id, p.user_id AS userId, p.category_id AS categoryId, c.name AS categoryName, p.title, LEFT(p.content, 200) AS content, p.images, p.view_count AS viewCount, p.like_count AS likeCount, p.comment_count AS commentCount, p.collect_count AS collectCount, p.is_top AS isTop, p.is_essence AS isEssence, p.ai_category AS aiCategory, p.create_time AS createTime, u.id AS authorId, u.nickname AS authorNickname, u.avatar AS authorAvatar FROM forum_post p LEFT JOIN forum_category c ON p.category_id = c.id LEFT JOIN sys_user u ON p.user_id = u.id
p.status = 0
AND c.type = #{type}
AND p.category_id = #{categoryId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.is_top DESC, p.create_time DESC
